def generate_image(prompt, model_ref=None, input=None, **_extra):
    import json, os, datetime, time, uuid, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0015000" if __import__("os").path.isdir("./environment_mix/0015000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _new_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    def _is_obj(v):
        return isinstance(v, dict)

    def _valid_prompt(s):
        return isinstance(s, str) and len(s.strip()) > 0

    def _valid_model_ref(s):
        if s is None:
            return True
        if not isinstance(s, str) or not s.strip():
            return False
        s = s.strip()
        # Accept typical Replicate refs: owner/name, owner/name:version, owner/name@sha256:...
        if re.match(r"^[A-Za-z0-9_.-]+/[A-Za-z0-9_.-]+([:@][A-Za-z0-9_.:-]+)?$", s):
            return True
        return False

    def _pick_active_key(api_keys):
        active = [k for k in api_keys if isinstance(k, dict) and k.get("status") == "active" and k.get("id")]
        # Ambient auth: choose a working active key if any exists
        return active[0] if active else None

    def _within_24h(ts_iso, cutoff):
        if not isinstance(ts_iso, str):
            return False
        try:
            s = ts_iso.replace("Z", "+00:00")
            dt = datetime.datetime.fromisoformat(s)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt >= cutoff
        except Exception:
            return False

    def _enforce_quota(api_key_row, usage_events, tool_name):
        # Only enforce for mutating tools per rules
        try:
            rq = int(api_key_row.get("daily_request_quota", 0))
            cq = int(api_key_row.get("daily_compute_ms_quota", 0))
        except Exception:
            return _err("VALIDATION_ERROR", "API key quota fields are invalid.")
        if rq < 0 or cq < 0:
            return _err("VALIDATION_ERROR", "API key quota fields must be non-negative.")

        cutoff = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc) - datetime.timedelta(hours=24)
        recent = [e for e in usage_events if isinstance(e, dict) and e.get("api_key_id") == api_key_row["id"] and _within_24h(e.get("created_at"), cutoff)]
        used_req = len(recent)
        used_ms = 0
        for e in recent:
            try:
                used_ms += int(e.get("compute_ms", 0) or 0)
            except Exception:
                used_ms += 0

        if used_req >= rq:
            return _err("QUOTA_EXCEEDED", "Daily request quota exceeded.", limit=rq, used=used_req, scope="requests_24h")
        if used_ms > cq:
            return _err("QUOTA_EXCEEDED", "Daily compute quota exceeded.", limit=cq, used=used_ms, scope="compute_ms_24h")
        return None

    def _log_usage(usage_events, api_key_id, tool_name, status, job_id=None, prediction_id=None, request_payload=None, response_summary=None, compute_ms=0):
        ev = {
            "id": _new_id("ue"),
            "api_key_id": api_key_id,
            "tool_name": tool_name,
            "job_id": job_id,
            "prediction_id": prediction_id,
            "request_payload": request_payload,
            "response_summary": response_summary,
            "compute_ms": int(compute_ms) if isinstance(compute_ms, int) and compute_ms >= 0 else 0,
            "created_at": now,
            "updated_at": now,
        }
        usage_events.append(ev)
        _save("usage_events.json", usage_events)
        return ev

    def _derive_job_status(preds):
        if not preds:
            return "queued"
        sts = [p.get("status") for p in preds if isinstance(p, dict)]
        if any(s in ("starting", "processing") for s in sts):
            return "running"
        if any(s == "failed" for s in sts):
            return "failed"
        if any(s == "canceled" for s in sts):
            return "cancelled"
        if sts and all(s == "succeeded" for s in sts):
            return "succeeded"
        return "queued"

    # Validate inputs
    if not _valid_prompt(prompt):
        # log attempt if possible (after auth), but input invalid can be logged only if authenticated; still validate first as required
        return _err("VALIDATION_ERROR", "prompt is required and must be a non-empty string.")
    if input is not None and not _is_obj(input):
        return _err("VALIDATION_ERROR", "input must be an object when provided.")
    if not _valid_model_ref(model_ref):
        return _err("VALIDATION_ERROR", "model_ref is not a valid Replicate reference.")
    if model_ref is None:
        model_ref = "black-forest-labs/flux-schnell"

    # Authenticate (ambient)
    api_keys = _load("api_keys.json")
    api_key = _pick_active_key(api_keys)
    if not api_key:
        return _err("UNAUTHORIZED", "No active API key available for this request.")

    # Load usage and enforce quota
    usage_events = _load("usage_events.json")
    qerr = _enforce_quota(api_key, usage_events, "generate_image")
    if qerr:
        _log_usage(
            usage_events, api_key["id"], "generate_image", "error",
            request_payload={"prompt": prompt, "model_ref": model_ref, "input": input},
            response_summary={"error": qerr["error"]["code"]},
            compute_ms=0
        )
        return qerr

    # Persist job + prediction
    generation_jobs = _load("generation_jobs.json")
    replicate_predictions = _load("replicate_predictions.json")
    prediction_outputs = _load("prediction_outputs.json")

    job_id = _new_id("job")
    pred_id = _new_id("pred")

    # Replicate prediction id uniqueness
    replicate_prediction_id = f"rp_{uuid.uuid4().hex}"
    if any(isinstance(p, dict) and p.get("replicate_prediction_id") == replicate_prediction_id for p in replicate_predictions):
        # Extremely unlikely; regenerate a few times
        for _ in range(5):
            replicate_prediction_id = f"rp_{uuid.uuid4().hex}"
            if not any(isinstance(p, dict) and p.get("replicate_prediction_id") == replicate_prediction_id for p in replicate_predictions):
                break
        else:
            q = _err("CONFLICT", "Could not allocate unique replicate_prediction_id.")
            _log_usage(usage_events, api_key["id"], "generate_image", "error",
                       request_payload={"prompt": prompt, "model_ref": model_ref, "input": input},
                       response_summary={"error": q["error"]["code"]},
                       compute_ms=0)
            return q

    job_input = {"prompt": prompt}
    if input:
        # store passthrough params alongside prompt
        job_input.update(input)

    job = {
        "id": job_id,
        "api_key_id": api_key["id"],
        "tool_name": "generate_image",
        "model_provider": "replicate",
        "model_ref": model_ref,
        "job_type": "single_image",
        "input": job_input,
        "requested_outputs": 1,
        "status": "queued",
        "error_message": None,
        "created_at": now,
        "updated_at": now,
    }

    # replicate_predictions.input should be the payload sent to Replicate (normalized here)
    replicate_input = {"prompt": prompt}
    if input:
        replicate_input.update(input)

    pred = {
        "id": pred_id,
        "job_id": job_id,
        "api_key_id": api_key["id"],
        "replicate_prediction_id": replicate_prediction_id,
        "replicate_model_ref": model_ref,
        "input": replicate_input,
        "status": "starting",
        "replicate_created_at": now,
        "replicate_completed_at": None,
        "logs": None,
        "error_message": None,
        "metrics": None,
        "created_at": now,
        "updated_at": now,
    }

    # Derive job status from child prediction
    job["status"] = _derive_job_status([pred])

    generation_jobs.append(job)
    replicate_predictions.append(pred)
    _save("generation_jobs.json", generation_jobs)
    _save("replicate_predictions.json", replicate_predictions)

    # Update API key last_used_at
    api_key["last_used_at"] = now
    api_key["updated_at"] = now
    for i, k in enumerate(api_keys):
        if isinstance(k, dict) and k.get("id") == api_key["id"]:
            api_keys[i] = api_key
            break
    _save("api_keys.json", api_keys)

    # Usage log (success)
    _log_usage(
        usage_events, api_key["id"], "generate_image", "success",
        job_id=job_id, prediction_id=pred_id,
        request_payload={"prompt": prompt, "model_ref": model_ref, "input": input},
        response_summary={"job_id": job_id, "prediction_id": pred_id, "replicate_prediction_id": replicate_prediction_id},
        compute_ms=0
    )

    # Include any existing outputs for this prediction (usually none at creation)
    outs = [o for o in prediction_outputs if isinstance(o, dict) and o.get("prediction_id") == pred_id]
    return {
        "job": job,
        "prediction": pred,
        "outputs": outs,
        "meta": {
            "latency_ms": int((time.time() - t0) * 1000)
        }
    }

def generate_multiple_images(prompts, model_ref=None, input=None, **_extra):
    import json, os, datetime, time, uuid, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0015000" if __import__("os").path.isdir("./environment_mix/0015000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _new_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    def _is_obj(v):
        return isinstance(v, dict)

    def _valid_model_ref(s):
        if s is None:
            return True
        if not isinstance(s, str) or not s.strip():
            return False
        s = s.strip()
        return re.match(r"^[A-Za-z0-9_.-]+/[A-Za-z0-9_.-]+([:@][A-Za-z0-9_.:-]+)?$", s) is not None

    def _pick_active_key(api_keys):
        active = [k for k in api_keys if isinstance(k, dict) and k.get("status") == "active" and k.get("id")]
        return active[0] if active else None

    def _within_24h(ts_iso, cutoff):
        if not isinstance(ts_iso, str):
            return False
        try:
            s = ts_iso.replace("Z", "+00:00")
            dt = datetime.datetime.fromisoformat(s)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt >= cutoff
        except Exception:
            return False

    def _enforce_quota(api_key_row, usage_events):
        try:
            rq = int(api_key_row.get("daily_request_quota", 0))
            cq = int(api_key_row.get("daily_compute_ms_quota", 0))
        except Exception:
            return _err("VALIDATION_ERROR", "API key quota fields are invalid.")
        if rq < 0 or cq < 0:
            return _err("VALIDATION_ERROR", "API key quota fields must be non-negative.")

        cutoff = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc) - datetime.timedelta(hours=24)
        recent = [e for e in usage_events if isinstance(e, dict) and e.get("api_key_id") == api_key_row["id"] and _within_24h(e.get("created_at"), cutoff)]
        used_req = len(recent)
        used_ms = 0
        for e in recent:
            try:
                used_ms += int(e.get("compute_ms", 0) or 0)
            except Exception:
                used_ms += 0

        if used_req >= rq:
            return _err("QUOTA_EXCEEDED", "Daily request quota exceeded.", limit=rq, used=used_req, scope="requests_24h")
        if used_ms > cq:
            return _err("QUOTA_EXCEEDED", "Daily compute quota exceeded.", limit=cq, used=used_ms, scope="compute_ms_24h")
        return None

    def _log_usage(usage_events, api_key_id, tool_name, status, job_id=None, prediction_id=None, request_payload=None, response_summary=None, compute_ms=0):
        ev = {
            "id": _new_id("ue"),
            "api_key_id": api_key_id,
            "tool_name": tool_name,
            "job_id": job_id,
            "prediction_id": prediction_id,
            "request_payload": request_payload,
            "response_summary": response_summary,
            "compute_ms": int(compute_ms) if isinstance(compute_ms, int) and compute_ms >= 0 else 0,
            "created_at": now,
            "updated_at": now,
        }
        usage_events.append(ev)
        _save("usage_events.json", usage_events)
        return ev

    def _derive_job_status(preds):
        if not preds:
            return "queued"
        sts = [p.get("status") for p in preds if isinstance(p, dict)]
        if any(s in ("starting", "processing") for s in sts):
            return "running"
        if any(s == "failed" for s in sts):
            return "failed"
        if any(s == "canceled" for s in sts):
            return "cancelled"
        if sts and all(s == "succeeded" for s in sts):
            return "succeeded"
        return "queued"

    # Validate
    if not isinstance(prompts, list) or len(prompts) == 0:
        return _err("VALIDATION_ERROR", "prompts is required and must be a non-empty array of strings.")
    cleaned = []
    for i, p in enumerate(prompts):
        if not isinstance(p, str) or not p.strip():
            return _err("VALIDATION_ERROR", f"prompts[{i}] must be a non-empty string.")
        cleaned.append(p.strip())
    if input is not None and not _is_obj(input):
        return _err("VALIDATION_ERROR", "input must be an object when provided.")
    if not _valid_model_ref(model_ref):
        return _err("VALIDATION_ERROR", "model_ref is not a valid Replicate reference.")
    if model_ref is None:
        model_ref = "black-forest-labs/flux-schnell"

    api_keys = _load("api_keys.json")
    api_key = _pick_active_key(api_keys)
    if not api_key:
        return _err("UNAUTHORIZED", "No active API key available for this request.")

    usage_events = _load("usage_events.json")
    qerr = _enforce_quota(api_key, usage_events)
    if qerr:
        _log_usage(
            usage_events, api_key["id"], "generate_multiple_images", "error",
            request_payload={"prompts": prompts, "model_ref": model_ref, "input": input},
            response_summary={"error": qerr["error"]["code"]},
            compute_ms=0
        )
        return qerr

    generation_jobs = _load("generation_jobs.json")
    replicate_predictions = _load("replicate_predictions.json")
    prediction_outputs = _load("prediction_outputs.json")

    job_id = _new_id("job")
    job_input = {"prompts": cleaned}
    if input:
        job_input.update(input)

    requested_outputs = len(cleaned)
    if requested_outputs < 1:
        return _err("VALIDATION_ERROR", "requested_outputs must be >= 1.")

    job = {
        "id": job_id,
        "api_key_id": api_key["id"],
        "tool_name": "generate_multiple_images",
        "model_provider": "replicate",
        "model_ref": model_ref,
        "job_type": "multi_prompt_batch",
        "input": job_input,
        "requested_outputs": requested_outputs,
        "status": "queued",
        "error_message": None,
        "created_at": now,
        "updated_at": now,
    }

    # Create one prediction per prompt
    created_preds = []
    existing_rpids = set(p.get("replicate_prediction_id") for p in replicate_predictions if isinstance(p, dict))
    for ptxt in cleaned:
        rp_id = f"rp_{uuid.uuid4().hex}"
        tries = 0
        while rp_id in existing_rpids and tries < 10:
            rp_id = f"rp_{uuid.uuid4().hex}"
            tries += 1
        if rp_id in existing_rpids:
            q = _err("CONFLICT", "Could not allocate unique replicate_prediction_id.")
            _log_usage(usage_events, api_key["id"], "generate_multiple_images", "error",
                       request_payload={"prompts": prompts, "model_ref": model_ref, "input": input},
                       response_summary={"error": q["error"]["code"]},
                       compute_ms=0)
            return q
        existing_rpids.add(rp_id)

        rid = _new_id("pred")
        replicate_input = {"prompt": ptxt}
        if input:
            replicate_input.update(input)

        pred = {
            "id": rid,
            "job_id": job_id,
            "api_key_id": api_key["id"],
            "replicate_prediction_id": rp_id,
            "replicate_model_ref": model_ref,
            "input": replicate_input,
            "status": "starting",
            "replicate_created_at": now,
            "replicate_completed_at": None,
            "logs": None,
            "error_message": None,
            "metrics": None,
            "created_at": now,
            "updated_at": now,
        }
        replicate_predictions.append(pred)
        created_preds.append(pred)

    job["status"] = _derive_job_status(created_preds)

    generation_jobs.append(job)
    _save("generation_jobs.json", generation_jobs)
    _save("replicate_predictions.json", replicate_predictions)

    # Update API key last_used_at
    api_key["last_used_at"] = now
    api_key["updated_at"] = now
    for i, k in enumerate(api_keys):
        if isinstance(k, dict) and k.get("id") == api_key["id"]:
            api_keys[i] = api_key
            break
    _save("api_keys.json", api_keys)

    _log_usage(
        usage_events, api_key["id"], "generate_multiple_images", "success",
        job_id=job_id, prediction_id=None,
        request_payload={"prompts": prompts, "model_ref": model_ref, "input": input},
        response_summary={"job_id": job_id, "predictions_created": len(created_preds)},
        compute_ms=0
    )

    # Include outputs grouped per prediction (usually empty at creation)
    outputs_by_pred = {}
    for pred in created_preds:
        pid = pred["id"]
        outs = [o for o in prediction_outputs if isinstance(o, dict) and o.get("prediction_id") == pid]
        outputs_by_pred[pid] = outs

    return {
        "job": job,
        "predictions": created_preds,
        "outputs_by_prediction": outputs_by_pred,
        "meta": {
            "latency_ms": int((time.time() - t0) * 1000),
            "requested_outputs": requested_outputs
        }
    }

