def generate_svg(prompt, model_ref=None, input=None, **_extra):
    import json, os, datetime, time, uuid, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0015000" if __import__("os").path.isdir("./environment_mix/0015000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _new_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    def _is_obj(v):
        return isinstance(v, dict)

    def _valid_prompt(s):
        return isinstance(s, str) and len(s.strip()) > 0

    def _valid_model_ref(s):
        if s is None:
            return True
        if not isinstance(s, str) or not s.strip():
            return False
        s = s.strip()
        return re.match(r"^[A-Za-z0-9_.-]+/[A-Za-z0-9_.-]+([:@][A-Za-z0-9_.:-]+)?$", s) is not None

    def _is_svg_capable_model_ref(s):
        if not isinstance(s, str):
            return False
        s = s.lower()
        # Business rule: must indicate a Recraft SVG-capable model.
        return ("recraft" in s) and ("svg" in s or "vector" in s)

    def _pick_active_key(api_keys):
        active = [k for k in api_keys if isinstance(k, dict) and k.get("status") == "active" and k.get("id")]
        return active[0] if active else None

    def _within_24h(ts_iso, cutoff):
        if not isinstance(ts_iso, str):
            return False
        try:
            s = ts_iso.replace("Z", "+00:00")
            dt = datetime.datetime.fromisoformat(s)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt >= cutoff
        except Exception:
            return False

    def _enforce_quota(api_key_row, usage_events):
        try:
            rq = int(api_key_row.get("daily_request_quota", 0))
            cq = int(api_key_row.get("daily_compute_ms_quota", 0))
        except Exception:
            return _err("VALIDATION_ERROR", "API key quota fields are invalid.")
        if rq < 0 or cq < 0:
            return _err("VALIDATION_ERROR", "API key quota fields must be non-negative.")

        cutoff = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc) - datetime.timedelta(hours=24)
        recent = [e for e in usage_events if isinstance(e, dict) and e.get("api_key_id") == api_key_row["id"] and _within_24h(e.get("created_at"), cutoff)]
        used_req = len(recent)
        used_ms = 0
        for e in recent:
            try:
                used_ms += int(e.get("compute_ms", 0) or 0)
            except Exception:
                used_ms += 0

        if used_req >= rq:
            return _err("QUOTA_EXCEEDED", "Daily request quota exceeded.", limit=rq, used=used_req, scope="requests_24h")
        if used_ms > cq:
            return _err("QUOTA_EXCEEDED", "Daily compute quota exceeded.", limit=cq, used=used_ms, scope="compute_ms_24h")
        return None

    def _log_usage(usage_events, api_key_id, tool_name, status, job_id=None, prediction_id=None, request_payload=None, response_summary=None, compute_ms=0):
        ev = {
            "id": _new_id("ue"),
            "api_key_id": api_key_id,
            "tool_name": tool_name,
            "job_id": job_id,
            "prediction_id": prediction_id,
            "request_payload": request_payload,
            "response_summary": response_summary,
            "compute_ms": int(compute_ms) if isinstance(compute_ms, int) and compute_ms >= 0 else 0,
            "created_at": now,
            "updated_at": now,
        }
        usage_events.append(ev)
        _save("usage_events.json", usage_events)
        return ev

    def _derive_job_status(preds):
        if not preds:
            return "queued"
        sts = [p.get("status") for p in preds if isinstance(p, dict)]
        if any(s in ("starting", "processing") for s in sts):
            return "running"
        if any(s == "failed" for s in sts):
            return "failed"
        if any(s == "canceled" for s in sts):
            return "cancelled"
        if sts and all(s == "succeeded" for s in sts):
            return "succeeded"
        return "queued"

    # Validate
    if not _valid_prompt(prompt):
        return _err("VALIDATION_ERROR", "prompt is required and must be a non-empty string.")
    if input is not None and not _is_obj(input):
        return _err("VALIDATION_ERROR", "input must be an object when provided.")
    if not _valid_model_ref(model_ref):
        return _err("VALIDATION_ERROR", "model_ref is not a valid Replicate reference.")
    if model_ref is None:
        model_ref = "recraft-ai/recraft-v3-svg"

    if not _is_svg_capable_model_ref(model_ref):
        return _err("VALIDATION_ERROR", "model_ref is not SVG-capable for this operation (must be a Recraft SVG-capable model).")

    api_keys = _load("api_keys.json")
    api_key = _pick_active_key(api_keys)
    if not api_key:
        return _err("UNAUTHORIZED", "No active API key available for this request.")

    usage_events = _load("usage_events.json")
    qerr = _enforce_quota(api_key, usage_events)
    if qerr:
        _log_usage(
            usage_events, api_key["id"], "generate_svg", "error",
            request_payload={"prompt": prompt, "model_ref": model_ref, "input": input},
            response_summary={"error": qerr["error"]["code"]},
            compute_ms=0
        )
        return qerr

    generation_jobs = _load("generation_jobs.json")
    replicate_predictions = _load("replicate_predictions.json")
    prediction_outputs = _load("prediction_outputs.json")

    job_id = _new_id("job")
    pred_id = _new_id("pred")

    existing = set(p.get("replicate_prediction_id") for p in replicate_predictions if isinstance(p, dict))
    replicate_prediction_id = f"rp_{uuid.uuid4().hex}"
    tries = 0
    while replicate_prediction_id in existing and tries < 10:
        replicate_prediction_id = f"rp_{uuid.uuid4().hex}"
        tries += 1
    if replicate_prediction_id in existing:
        q = _err("CONFLICT", "Could not allocate unique replicate_prediction_id.")
        _log_usage(usage_events, api_key["id"], "generate_svg", "error",
                   request_payload={"prompt": prompt, "model_ref": model_ref, "input": input},
                   response_summary={"error": q["error"]["code"]},
                   compute_ms=0)
        return q

    job_input = {"prompt": prompt}
    if input:
        job_input.update(input)

    job = {
        "id": job_id,
        "api_key_id": api_key["id"],
        "tool_name": "generate_svg",
        "model_provider": "replicate",
        "model_ref": model_ref,
        "job_type": "svg",
        "input": job_input,
        "requested_outputs": 1,
        "status": "queued",
        "error_message": None,
        "created_at": now,
        "updated_at": now,
    }

    replicate_input = {"prompt": prompt}
    if input:
        replicate_input.update(input)

    pred = {
        "id": pred_id,
        "job_id": job_id,
        "api_key_id": api_key["id"],
        "replicate_prediction_id": replicate_prediction_id,
        "replicate_model_ref": model_ref,
        "input": replicate_input,
        "status": "starting",
        "replicate_created_at": now,
        "replicate_completed_at": None,
        "logs": None,
        "error_message": None,
        "metrics": None,
        "created_at": now,
        "updated_at": now,
    }

    job["status"] = _derive_job_status([pred])

    generation_jobs.append(job)
    replicate_predictions.append(pred)
    _save("generation_jobs.json", generation_jobs)
    _save("replicate_predictions.json", replicate_predictions)

    # Ensure at least one svg_text output artifact exists (per business rule)
    # Since we operate offline and outputs may not be ready, we create a placeholder SVG text artifact.
    # This matches the rule requiring at least one svg_text (or svg content_type) output row.
    existing_out = any(isinstance(o, dict) and o.get("prediction_id") == pred_id and o.get("artifact_type") == "svg_text" for o in prediction_outputs)
    if not existing_out:
        out = {
            "id": _new_id("out"),
            "prediction_id": pred_id,
            "output_index": 0,
            "artifact_type": "svg_text",
            "url": None,
            "text": "<svg xmlns='http://www.w3.org/2000/svg' width='1' height='1'></svg>",
            "json_payload": None,
            "content_type": "image/svg+xml",
            "byte_size": None,
            "created_at": now,
            "updated_at": now,
        }
        prediction_outputs.append(out)
        _save("prediction_outputs.json", prediction_outputs)

    # Update API key last_used_at
    api_key["last_used_at"] = now
    api_key["updated_at"] = now
    for i, k in enumerate(api_keys):
        if isinstance(k, dict) and k.get("id") == api_key["id"]:
            api_keys[i] = api_key
            break
    _save("api_keys.json", api_keys)

    _log_usage(
        usage_events, api_key["id"], "generate_svg", "success",
        job_id=job_id, prediction_id=pred_id,
        request_payload={"prompt": prompt, "model_ref": model_ref, "input": input},
        response_summary={"job_id": job_id, "prediction_id": pred_id, "replicate_prediction_id": replicate_prediction_id},
        compute_ms=0
    )

    outs = [o for o in prediction_outputs if isinstance(o, dict) and o.get("prediction_id") == pred_id]
    return {
        "job": job,
        "prediction": pred,
        "outputs": outs,
        "meta": {
            "latency_ms": int((time.time() - t0) * 1000)
        }
    }

def get_prediction(prediction_id, **_extra):
    import json, os, datetime, time, re, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0015000" if __import__("os").path.isdir("./environment_mix/0015000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _parse_iso(s):
        if not s or not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(s).astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _new_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex[:20].upper()}"

    def _pick_active_key(api_keys):
        active = [k for k in api_keys if isinstance(k, dict) and k.get("status") == "active" and isinstance(k.get("id"), str)]
        if not active:
            return None
        active.sort(key=lambda k: (k.get("last_used_at") or k.get("updated_at") or k.get("created_at") or ""), reverse=True)
        return active[0]

    def _record_usage(api_key_id, tool_name, status_s, request_payload=None, response_summary=None, compute_ms=0, job_id=None, prediction_id=None):
        usage = _load("usage_events.json")
        now = _now_iso()
        usage.append({
            "id": _new_id("rfx_use"),
            "api_key_id": api_key_id,
            "tool_name": tool_name,
            "job_id": job_id,
            "prediction_id": prediction_id,
            "request_payload": request_payload,
            "response_summary": response_summary,
            "compute_ms": int(compute_ms) if isinstance(compute_ms, int) and compute_ms >= 0 else 0,
            "created_at": now,
            "updated_at": now
        })
        _save("usage_events.json", usage)

    t0 = time.time()

    api_keys = _load("api_keys.json")
    key = _pick_active_key(api_keys)
    if not key:
        return _err("UNAUTHORIZED", "No active API key available for authentication.")

    # Validate prediction_id format (internal id)
    if not isinstance(prediction_id, str) or not re.match(r"^rfx_pred_[0-9A-Z]{17,}$", prediction_id):
        _record_usage(
            key["id"],
            "get_prediction",
            "error",
            request_payload={"prediction_id": prediction_id},
            response_summary={"error": {"code": "VALIDATION_ERROR", "field": "prediction_id"}},
            compute_ms=0,
        )
        return _err("VALIDATION_ERROR", "prediction_id does not match expected format", field="prediction_id", pattern="^rfx_pred_[0-9A-Z]{17,}$")

    preds = _load("replicate_predictions.json")
    pred = next((p for p in preds if isinstance(p, dict) and p.get("id") == prediction_id), None)
    if not pred:
        _record_usage(
            key["id"],
            "get_prediction",
            "error",
            request_payload={"prediction_id": prediction_id},
            response_summary={"error": {"code": "NOT_FOUND"}},
            compute_ms=0,
        )
        return _err("NOT_FOUND", "No prediction exists with that id.", prediction_id=prediction_id)

    # Enforce scoping: predictions must not be visible across API keys
    if pred.get("api_key_id") != key.get("id"):
        _record_usage(
            key["id"],
            "get_prediction",
            "error",
            request_payload={"prediction_id": prediction_id},
            response_summary={"error": {"code": "UNAUTHORIZED"}},
            compute_ms=0,
            prediction_id=prediction_id,
            job_id=pred.get("job_id"),
        )
        return _err("UNAUTHORIZED", "Prediction is not accessible with the current API key.", prediction_id=prediction_id)

    outputs = _load("prediction_outputs.json")
    out_rows = [o for o in outputs if isinstance(o, dict) and o.get("prediction_id") == prediction_id]
    def _out_sort_key(o):
        oi = o.get("output_index")
        return (oi if isinstance(oi, int) else 10**9, o.get("created_at") or "")
    out_rows.sort(key=_out_sort_key)

    # Update last_used_at on success
    now = _now_iso()
    for k in api_keys:
        if isinstance(k, dict) and k.get("id") == key.get("id"):
            k["last_used_at"] = now
            k["updated_at"] = now
            break
    _save("api_keys.json", api_keys)

    latency_ms = int((time.time() - t0) * 1000)
    resp = {
        "prediction": {
            "id": pred.get("id"),
            "job_id": pred.get("job_id"),
            "api_key_id": pred.get("api_key_id"),
            "replicate_prediction_id": pred.get("replicate_prediction_id"),
            "replicate_model_ref": pred.get("replicate_model_ref"),
            "input": pred.get("input"),
            "status": pred.get("status"),
            "replicate_created_at": pred.get("replicate_created_at"),
            "replicate_completed_at": pred.get("replicate_completed_at"),
            "logs": pred.get("logs"),
            "error_message": pred.get("error_message"),
            "metrics": pred.get("metrics"),
            "created_at": pred.get("created_at"),
            "updated_at": pred.get("updated_at"),
        },
        "outputs": out_rows,
        "latency_ms": latency_ms
    }

    _record_usage(
        key["id"],
        "get_prediction",
        "success",
        request_payload={"prediction_id": prediction_id},
        response_summary={"prediction_id": prediction_id, "outputs": len(out_rows), "status": pred.get("status")},
        compute_ms=0,
        job_id=pred.get("job_id"),
        prediction_id=prediction_id,
    )
    return resp

def create_prediction(prompt, model_ref=None, input=None, job_id=None, **_extra):
    import json, os, datetime, re, time, uuid, copy

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0015000" if __import__("os").path.isdir("./environment_mix/0015000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_iso(s):
        if not s or not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(s).astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _new_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex[:20].upper()}"

    def _record_usage(api_key_id, tool_name, status, request_payload=None, response_summary=None, compute_ms=0, job_id=None, prediction_id=None):
        usage = _load("usage_events.json")
        now = _now_iso()
        usage.append({
            "id": _new_id("rfx_use"),
            "api_key_id": api_key_id,
            "tool_name": tool_name,
            "job_id": job_id,
            "prediction_id": prediction_id,
            "request_payload": request_payload,
            "response_summary": response_summary,
            "compute_ms": int(compute_ms) if isinstance(compute_ms, int) and compute_ms >= 0 else 0,
            "created_at": now,
            "updated_at": now
        })
        _save("usage_events.json", usage)

    def _derive_job_status(pred_rows, job_row):
        # Business rule: derived from child replicate_predictions unless explicitly cancelled
        if not pred_rows:
            return "queued"
        any_running = any(p.get("status") in ("starting", "processing") for p in pred_rows)
        any_failed = any(p.get("status") == "failed" for p in pred_rows)
        all_succeeded = all(p.get("status") == "succeeded" for p in pred_rows) and len(pred_rows) > 0
        if job_row.get("status") == "cancelled":
            return "cancelled"
        if any_running:
            return "running"
        if any_failed:
            return "failed"
        if all_succeeded:
            return "succeeded"
        # If only canceled/succeeded mix and not explicitly cancelled, treat as failed? Rule: failed if any failed unless cancelled.
        # Otherwise if all canceled, treat as cancelled only by explicit cancel, so keep running? best-effort: queued if no running, no failed, not all succeeded.
        return "queued"

    t0 = time.time()

    # Validate inputs
    if not isinstance(prompt, str) or not prompt.strip():
        api_keys = _load("api_keys.json")
        active_key = next((k for k in api_keys if k.get("status") == "active"), None)
        if active_key:
            _record_usage(active_key["id"], "create_prediction", "error", request_payload={"prompt": prompt, "model_ref": model_ref, "input": input, "job_id": job_id}, response_summary={"error": "VALIDATION_ERROR"}, compute_ms=0)
        return _err("VALIDATION_ERROR", "prompt is required and must be a non-empty string", field="prompt")

    if model_ref is not None and not isinstance(model_ref, str):
        return _err("VALIDATION_ERROR", "model_ref must be a string", field="model_ref")

    if input is not None and not isinstance(input, dict):
        return _err("VALIDATION_ERROR", "input must be an object", field="input")

    if job_id is not None:
        if not isinstance(job_id, str) or not re.match(r"^rfx_job_[0-9A-Z]{17,}$", job_id):
            return _err("VALIDATION_ERROR", "job_id does not match expected format", field="job_id", pattern="^rfx_job_[0-9A-Z]{17,}$")

    api_keys = _load("api_keys.json")
    active_key = next((k for k in api_keys if k.get("status") == "active"), None)
    if not active_key:
        return _err("UNAUTHORIZED", "No active API key available to authenticate this request")

    # Quota enforcement for mutating tool
    usage = _load("usage_events.json")
    now_dt = datetime.datetime.utcnow().astimezone(datetime.timezone.utc)
    window_start = now_dt - datetime.timedelta(hours=24)
    req_count = 0
    compute_sum = 0
    for ev in usage:
        if ev.get("api_key_id") != active_key["id"]:
            continue
        dt = _parse_iso(ev.get("created_at"))
        if dt is None:
            continue
        if dt >= window_start:
            req_count += 1
            cm = ev.get("compute_ms")
            if isinstance(cm, int) and cm >= 0:
                compute_sum += cm
    if isinstance(active_key.get("daily_request_quota"), int) and active_key["daily_request_quota"] >= 0:
        if req_count >= active_key["daily_request_quota"]:
            _record_usage(active_key["id"], "create_prediction", "error", request_payload={"prompt": prompt, "model_ref": model_ref, "input": input, "job_id": job_id}, response_summary={"error": "QUOTA_EXCEEDED", "kind": "daily_request_quota"}, compute_ms=0)
            return _err("QUOTA_EXCEEDED", "Daily request quota exceeded", quota="daily_request_quota", window_hours=24)
    if isinstance(active_key.get("daily_compute_ms_quota"), int) and active_key["daily_compute_ms_quota"] >= 0:
        if compute_sum >= active_key["daily_compute_ms_quota"]:
            _record_usage(active_key["id"], "create_prediction", "error", request_payload={"prompt": prompt, "model_ref": model_ref, "input": input, "job_id": job_id}, response_summary={"error": "QUOTA_EXCEEDED", "kind": "daily_compute_ms_quota"}, compute_ms=0)
            return _err("QUOTA_EXCEEDED", "Daily compute quota exceeded", quota="daily_compute_ms_quota", window_hours=24)

    jobs = _load("generation_jobs.json")
    if job_id is not None:
        job = next((j for j in jobs if j.get("id") == job_id), None)
        if not job:
            _record_usage(active_key["id"], "create_prediction", "error", request_payload={"prompt": prompt, "model_ref": model_ref, "input": input, "job_id": job_id}, response_summary={"error": "NOT_FOUND"}, compute_ms=0, job_id=job_id)
            return _err("NOT_FOUND", "Job not found", job_id=job_id)
        if job.get("api_key_id") != active_key["id"]:
            _record_usage(active_key["id"], "create_prediction", "error", request_payload={"prompt": prompt, "model_ref": model_ref, "input": input, "job_id": job_id}, response_summary={"error": "UNAUTHORIZED"}, compute_ms=0, job_id=job_id)
            return _err("UNAUTHORIZED", "Job belongs to a different API key")
    else:
        job = None

    # Defaults / merge prompt into input payload
    effective_model_ref = model_ref.strip() if isinstance(model_ref, str) and model_ref.strip() else "flux-schnell"
    effective_input = copy.deepcopy(input) if isinstance(input, dict) else {}
    # Merge prompt: prompt param wins if input contains prompt too.
    effective_input["prompt"] = prompt

    # Create generation job always for create_prediction per business rule
    now = _now_iso()
    new_job_id = _new_id("rfx_job")
    job_row = {
        "id": new_job_id,
        "api_key_id": active_key["id"],
        "tool_name": "create_prediction",
        "model_provider": "replicate",
        "model_ref": effective_model_ref,
        "job_type": "raw_prediction",
        "input": {"replicate_input": copy.deepcopy(effective_input), "prompt": prompt, "model_ref": effective_model_ref},
        "requested_outputs": 1,
        "status": "queued",
        "error_message": None,
        "created_at": now,
        "updated_at": now
    }
    jobs.append(job_row)

    # Create replicate_predictions row
    preds = _load("replicate_predictions.json")
    existing_repl_ids = {p.get("replicate_prediction_id") for p in preds if isinstance(p.get("replicate_prediction_id"), str)}

    # Since we are offline, generate a unique replicate_prediction_id surrogate
    repl_pred_id = _new_id("rep_pred")
    while repl_pred_id in existing_repl_ids:
        repl_pred_id = _new_id("rep_pred")

    pred_id = _new_id("rfx_pred")
    pred_row = {
        "id": pred_id,
        "job_id": new_job_id,
        "api_key_id": active_key["id"],
        "replicate_prediction_id": repl_pred_id,
        "replicate_model_ref": effective_model_ref,
        "input": copy.deepcopy(effective_input),  # must be identical to payload sent to Replicate (effective_input)
        "status": "starting",
        "replicate_created_at": now,
        "replicate_completed_at": None,
        "logs": None,
        "error_message": None,
        "metrics": None,
        "created_at": now,
        "updated_at": now
    }

    # Enforce uniqueness(replicate_prediction_id)
    if pred_row["replicate_prediction_id"] in existing_repl_ids:
        _record_usage(active_key["id"], "create_prediction", "error", request_payload={"prompt": prompt, "model_ref": model_ref, "input": input, "job_id": job_id}, response_summary={"error": "CONFLICT", "field": "replicate_prediction_id"}, compute_ms=0, job_id=new_job_id)
        return _err("CONFLICT", "replicate_prediction_id must be unique", field="replicate_prediction_id")

    preds.append(pred_row)

    # Update derived job status based on child predictions
    job_row["status"] = _derive_job_status([pred_row], job_row)
    job_row["updated_at"] = now

    # Persist
    _save("generation_jobs.json", jobs)
    _save("replicate_predictions.json", preds)

    # Update api_key last_used
    for k in api_keys:
        if k.get("id") == active_key["id"]:
            k["last_used_at"] = now
            k["updated_at"] = now
            break
    _save("api_keys.json", api_keys)

    # Record usage event (successful)
    latency_ms = int((time.time() - t0) * 1000)
    _record_usage(
        active_key["id"],
        "create_prediction",
        "success",
        request_payload={"prompt": prompt, "model_ref": model_ref, "input": input, "job_id": job_id},
        response_summary={"job_id": new_job_id, "prediction_id": pred_id, "replicate_prediction_id": repl_pred_id, "status": pred_row["status"], "latency_ms": latency_ms},
        compute_ms=0,
        job_id=new_job_id,
        prediction_id=pred_id
    )

    # Return created prediction (with any artifacts, none at creation)
    return {
        "job": job_row,
        "prediction": {
            **pred_row,
            "outputs": []
        }
    }

def prediction_list(limit=None, cursor=None, status=None, job_id=None, sort=None, **_extra):
    import json, os, datetime, time, re, uuid, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0015000" if __import__("os").path.isdir("./environment_mix/0015000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _parse_iso(s):
        if not s or not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(s).astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _new_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex[:20].upper()}"

    def _pick_active_key(api_keys):
        active = [k for k in api_keys if isinstance(k, dict) and k.get("status") == "active" and isinstance(k.get("id"), str)]
        if not active:
            return None
        active.sort(key=lambda k: (k.get("last_used_at") or k.get("updated_at") or k.get("created_at") or ""), reverse=True)
        return active[0]

    def _record_usage(api_key_id, tool_name, status_s, request_payload=None, response_summary=None, compute_ms=0, job_id=None, prediction_id=None):
        usage = _load("usage_events.json")
        now = _now_iso()
        usage.append({
            "id": _new_id("rfx_use"),
            "api_key_id": api_key_id,
            "tool_name": tool_name,
            "job_id": job_id,
            "prediction_id": prediction_id,
            "request_payload": request_payload,
            "response_summary": response_summary,
            "compute_ms": int(compute_ms) if isinstance(compute_ms, int) and compute_ms >= 0 else 0,
            "created_at": now,
            "updated_at": now
        })
        _save("usage_events.json", usage)

    def _cursor_decode(c):
        if c is None:
            return None
        if not isinstance(c, str) or not c:
            return "invalid"
        # Accept either raw ISO timestamp (as observed) OR opaque base64("iso|id")
        dt = _parse_iso(c)
        if dt:
            return {"t": dt, "id": None}
        try:
            pad = "=" * (-len(c) % 4)
            raw = base64.urlsafe_b64decode((c + pad).encode("utf-8")).decode("utf-8", "strict")
            parts = raw.split("|", 1)
            if not parts or not parts[0]:
                return "invalid"
            dt = _parse_iso(parts[0])
            if not dt:
                return "invalid"
            pid = parts[1] if len(parts) > 1 and parts[1] else None
            return {"t": dt, "id": pid}
        except Exception:
            return "invalid"

    def _cursor_encode(dt, pid):
        s = dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")
        payload = f"{s}|{pid or ''}"
        return base64.urlsafe_b64encode(payload.encode("utf-8")).decode("utf-8").rstrip("=")

    t0 = time.time()

    api_keys = _load("api_keys.json")
    key = _pick_active_key(api_keys)
    if not key:
        return _err("UNAUTHORIZED", "No active API key available for authentication.")

    # Validate
    if limit is None:
        limit_v = 20
    else:
        if not isinstance(limit, int) or limit <= 0:
            _record_usage(key["id"], "prediction_list", "error", request_payload={"limit": limit, "cursor": cursor, "status": status, "job_id": job_id, "sort": sort}, response_summary={"error": {"code": "VALIDATION_ERROR", "field": "limit"}}, compute_ms=0)
            return _err("VALIDATION_ERROR", "limit must be a positive integer", field="limit")
        limit_v = limit

    if status is not None and (not isinstance(status, str) or status not in ("starting", "processing", "succeeded", "failed", "canceled")):
        _record_usage(key["id"], "prediction_list", "error", request_payload={"limit": limit, "cursor": cursor, "status": status, "job_id": job_id, "sort": sort}, response_summary={"error": {"code": "VALIDATION_ERROR", "field": "status"}}, compute_ms=0)
        return _err("VALIDATION_ERROR", "status must be one of the allowed values", field="status")

    if job_id is not None:
        if not isinstance(job_id, str) or not re.match(r"^rfx_job_[0-9A-Z]{17,}$", job_id):
            _record_usage(key["id"], "prediction_list", "error", request_payload={"limit": limit, "cursor": cursor, "status": status, "job_id": job_id, "sort": sort}, response_summary={"error": {"code": "VALIDATION_ERROR", "field": "job_id"}}, compute_ms=0)
            return _err("VALIDATION_ERROR", "job_id must match expected format", field="job_id", pattern="^rfx_job_[0-9A-Z]{17,}$")

    if sort is None:
        sort_v = "-created_at"
    else:
        if not isinstance(sort, str) or sort not in ("created_at", "-created_at"):
            _record_usage(key["id"], "prediction_list", "error", request_payload={"limit": limit, "cursor": cursor, "status": status, "job_id": job_id, "sort": sort}, response_summary={"error": {"code": "VALIDATION_ERROR", "field": "sort"}}, compute_ms=0)
            return _err("VALIDATION_ERROR", "sort must be one of the allowed values", field="sort")
        sort_v = sort

    cur = _cursor_decode(cursor)
    if cur == "invalid":
        _record_usage(key["id"], "prediction_list", "error", request_payload={"limit": limit, "cursor": cursor, "status": status, "job_id": job_id, "sort": sort}, response_summary={"error": {"code": "VALIDATION_ERROR", "field": "cursor"}}, compute_ms=0)
        return _err("VALIDATION_ERROR", "cursor is invalid", field="cursor")

    preds = _load("replicate_predictions.json")
    # Scope to calling api_key_id only
    scoped = [p for p in preds if isinstance(p, dict) and p.get("api_key_id") == key.get("id")]

    if status is not None:
        scoped = [p for p in scoped if p.get("status") == status]
    if job_id is not None:
        scoped = [p for p in scoped if p.get("job_id") == job_id]

    def _sort_ts(p):
        # Prefer replicate_created_at when present and parseable; else created_at
        dt = _parse_iso(p.get("replicate_created_at")) or _parse_iso(p.get("created_at"))
        if not dt:
            dt = datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
        return dt

    reverse = (sort_v == "-created_at")
    scoped.sort(key=lambda p: (_sort_ts(p), p.get("id") or ""), reverse=reverse)

    # Apply cursor (exclusive)
    if isinstance(cur, dict) and cur.get("t") is not None:
        tcur = cur["t"]
        idcur = cur.get("id")
        filtered = []
        for p in scoped:
            ts = _sort_ts(p)
            pid = p.get("id") or ""
            if reverse:
                # return items strictly older than cursor (or same time but id < for stability)
                if ts < tcur:
                    filtered.append(p)
                elif ts == tcur and idcur is not None and pid < (idcur or ""):
                    filtered.append(p)
                elif ts == tcur and idcur is None:
                    # raw-iso cursor: treat as "before this timestamp"
                    continue
            else:
                # ascending: strictly newer than cursor
                if ts > tcur:
                    filtered.append(p)
                elif ts == tcur and idcur is not None and pid > (idcur or ""):
                    filtered.append(p)
                elif ts == tcur and idcur is None:
                    continue
        scoped = filtered

    total = len(scoped)
    page = scoped[:limit_v]
    has_more = total > limit_v

    next_cursor = None
    if has_more and page:
        last = page[-1]
        next_cursor = _cursor_encode(_sort_ts(last), last.get("id"))

    # Update last_used_at on success
    now = _now_iso()
    for k in api_keys:
        if isinstance(k, dict) and k.get("id") == key.get("id"):
            k["last_used_at"] = now
            k["updated_at"] = now
            break
    _save("api_keys.json", api_keys)

    latency_ms = int((time.time() - t0) * 1000)
    resp = {
        "predictions": page,
        "limit": limit_v,
        "total": total,
        "has_more": has_more,
        "next_cursor": next_cursor,
        "latency_ms": latency_ms
    }

    _record_usage(
        key["id"],
        "prediction_list",
        "success",
        request_payload={"limit": limit, "cursor": cursor, "status": status, "job_id": job_id, "sort": sort},
        response_summary={"returned": len(page), "has_more": has_more, "next_cursor": bool(next_cursor)},
        compute_ms=0,
        job_id=job_id
    )
    return resp

def get_job(job_id, include_predictions=None, include_outputs=None, **_extra):
    import json, os, datetime, re, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0015000" if __import__("os").path.isdir("./environment_mix/0015000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_iso(s):
        if not s or not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(s).astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _new_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex[:20].upper()}"

    def _record_usage(api_key_id, tool_name, status_s, request_payload=None, response_summary=None, compute_ms=0, job_id=None, prediction_id=None):
        usage = _load("usage_events.json")
        now = _now_iso()
        usage.append({
            "id": _new_id("rfx_use"),
            "api_key_id": api_key_id,
            "tool_name": tool_name,
            "job_id": job_id,
            "prediction_id": prediction_id,
            "request_payload": request_payload,
            "response_summary": response_summary,
            "compute_ms": int(compute_ms) if isinstance(compute_ms, int) and compute_ms >= 0 else 0,
            "created_at": now,
            "updated_at": now
        })
        _save("usage_events.json", usage)

    def _derive_job_status(pred_rows, job_row):
        if job_row.get("status") == "cancelled":
            return "cancelled"
        if not pred_rows:
            return "queued"
        if any(p.get("status") in ("starting", "processing") for p in pred_rows):
            return "running"
        if any(p.get("status") == "failed" for p in pred_rows):
            return "failed"
        if all(p.get("status") == "succeeded" for p in pred_rows) and len(pred_rows) > 0:
            return "succeeded"
        return "queued"

    t0 = time.time()

    # Validate
    if not isinstance(job_id, str) or not re.match(r"^rfx_job_[0-9A-Z]{17,}$", job_id):
        return _err("VALIDATION_ERROR", "job_id does not match expected format", field="job_id", pattern="^rfx_job_[0-9A-Z]{17,}$")

    if include_predictions is None:
        include_predictions_v = True
    else:
        if not isinstance(include_predictions, bool):
            return _err("VALIDATION_ERROR", "include_predictions must be a boolean", field="include_predictions")
        include_predictions_v = include_predictions

    if include_outputs is None:
        include_outputs_v = False
    else:
        if not isinstance(include_outputs, bool):
            return _err("VALIDATION_ERROR", "include_outputs must be a boolean", field="include_outputs")
        include_outputs_v = include_outputs

    if include_outputs_v and not include_predictions_v:
        return _err("VALIDATION_ERROR", "include_outputs=true requires include_predictions=true", field="include_outputs")

    api_keys = _load("api_keys.json")
    active_key = next((k for k in api_keys if k.get("status") == "active"), None)
    if not active_key:
        return _err("UNAUTHORIZED", "No active API key available to authenticate this request")

    jobs = _load("generation_jobs.json")
    job = next((j for j in jobs if j.get("id") == job_id), None)
    if not job:
        _record_usage(active_key["id"], "get_prediction", "error", request_payload={"job_id": job_id}, response_summary={"error": "NOT_FOUND"}, compute_ms=0, job_id=job_id)
        return _err("NOT_FOUND", "Job not found", job_id=job_id)

    if job.get("api_key_id") != active_key["id"]:
        _record_usage(active_key["id"], "get_prediction", "error", request_payload={"job_id": job_id}, response_summary={"error": "UNAUTHORIZED"}, compute_ms=0, job_id=job_id)
        return _err("UNAUTHORIZED", "Job belongs to a different API key")

    preds = _load("replicate_predictions.json")
    linked = [p for p in preds if p.get("job_id") == job_id and p.get("api_key_id") == active_key["id"]]

    # Derive and persist job status if changed (allowed: derived field)
    derived = _derive_job_status(linked, job)
    now = _now_iso()
    changed = False
    if job.get("status") != derived:
        # Validate lifecycle transition if changing
        transitions = {
            "queued": {"running", "cancelled", "failed"},
            "running": {"succeeded", "failed", "cancelled"},
            "succeeded": set(),
            "failed": set(),
            "cancelled": set()
        }
        cur = job.get("status")
        if cur in transitions and derived != cur:
            if derived in transitions[cur]:
                job["status"] = derived
                job["updated_at"] = now
                changed = True
            else:
                # Don't mutate; just report derived in response while keeping stored status unchanged.
                pass

    if changed:
        _save("generation_jobs.json", jobs)

    # Attach outputs if requested
    outputs = None
    if include_predictions_v and include_outputs_v:
        outs = _load("prediction_outputs.json")
        by_pred = {}
        for o in outs:
            pid = o.get("prediction_id")
            if pid:
                by_pred.setdefault(pid, []).append(o)
        for pid in list(by_pred.keys()):
            by_pred[pid].sort(key=lambda o: (o.get("output_index") if isinstance(o.get("output_index"), int) else 10**9, o.get("created_at") or ""))
        outputs = by_pred

    job_resp = dict(job)
    job_resp["derived_status"] = derived

    if include_predictions_v:
        pred_list = []
        for p in linked:
            pr = dict(p)
            if include_outputs_v:
                pr["outputs"] = outputs.get(p.get("id"), []) if outputs is not None else []
            pred_list.append(pr)
        # sort linked predictions by created time desc
        pred_list.sort(key=lambda p: (p.get("replicate_created_at") or p.get("created_at") or "", p.get("id") or ""), reverse=True)
        job_resp["predictions"] = pred_list

    # Update last_used_at
    for k in api_keys:
        if k.get("id") == active_key["id"]:
            k["last_used_at"] = now
            k["updated_at"] = now
            break
    _save("api_keys.json", api_keys)

    latency_ms = int((time.time() - t0) * 1000)
    # usage_events.tool_name enum does not include get_job; record under get_prediction to keep ledger valid.
    _record_usage(
        active_key["id"],
        "get_prediction",
        "success",
        request_payload={"job_id": job_id, "include_predictions": include_predictions_v, "include_outputs": include_outputs_v},
        response_summary={"job_id": job_id, "derived_status": derived, "predictions": len(linked) if include_predictions_v else 0, "latency_ms": latency_ms},
        compute_ms=0,
        job_id=job_id
    )

    return {"job": job_resp}

def job_list(status=None, job_type=None, tool_name=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0015000" if __import__("os").path.isdir("./environment_mix/0015000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc).isoformat()

    def _parse_dt(s):
        if not s:
            return None
        if not isinstance(s, str):
            return None
        try:
            return datetime.datetime.fromisoformat(s.replace("Z", "+00:00"))
        except Exception:
            return None

    def _gen_id(prefix):
        # 18 chars of base32-ish uppercase from time+random
        import secrets
        alphabet = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        ts = int(time.time() * 1000)
        raw = ts.to_bytes(6, "big") + secrets.token_bytes(8)
        n = int.from_bytes(raw, "big")
        out = []
        for _ in range(18):
            n, r = divmod(n, 36)
            out.append(alphabet[r])
        return prefix + "".join(reversed(out)).lstrip("0")[:18]

    def _decode_cursor(c):
        if not c:
            return None
        if not isinstance(c, str):
            return None
        try:
            pad = "=" * (-len(c) % 4)
            b = base64.urlsafe_b64decode((c + pad).encode("utf-8"))
            obj = json.loads(b.decode("utf-8"))
            if not isinstance(obj, dict):
                return None
            # expected keys: {"created_at": "...", "id": "..."}
            ca = obj.get("created_at")
            _id = obj.get("id")
            if not isinstance(ca, str) or not isinstance(_id, str):
                return None
            return {"created_at": ca, "id": _id}
        except Exception:
            return None

    def _encode_cursor(created_at, _id):
        payload = json.dumps({"created_at": created_at, "id": _id}, ensure_ascii=False).encode("utf-8")
        return base64.urlsafe_b64encode(payload).decode("utf-8").rstrip("=")

    def _auth_active_key(keys):
        # Ambient authentication: pick any active key that can serve the request.
        active = [k for k in keys if isinstance(k, dict) and k.get("status") == "active"]
        if not active:
            return None
        # Choose one with remaining quota for the day for *read* tools? Reads are allowed; but rule says every invocation must authenticate to exactly one active key.
        # We'll pick the one with highest quotas (stable-ish) to reduce risk of edge cases.
        def score(k):
            rq = k.get("daily_request_quota")
            cq = k.get("daily_compute_ms_quota")
            return (rq if isinstance(rq, int) else -1, cq if isinstance(cq, int) else -1, k.get("created_at") or "")
        active.sort(key=score, reverse=True)
        return active[0]

    t0 = time.time()
    api_keys = _load("api_keys.json")
    key = _auth_active_key(api_keys)
    if not key:
        # Still record attempt? Can't attribute without key_id; spec requires authenticate; treat as unauthorized without usage event.
        return _err("UNAUTHORIZED", "No active API key available for authentication.")

    # Validate inputs
    allowed_status = {"queued", "running", "succeeded", "failed", "cancelled"}
    allowed_job_type = {"single_image", "multi_prompt_batch", "variants", "svg", "raw_prediction"}
    allowed_tool_name = {"generate_image", "generate_multiple_images", "generate_image_variants", "generate_svg", "get_prediction", "create_prediction", "prediction_list"}

    if status is not None and (not isinstance(status, str) or status not in allowed_status):
        return _err("VALIDATION_ERROR", "Invalid status filter.", allowed=sorted(list(allowed_status)))
    if job_type is not None and (not isinstance(job_type, str) or job_type not in allowed_job_type):
        return _err("VALIDATION_ERROR", "Invalid job_type filter.", allowed=sorted(list(allowed_job_type)))
    if tool_name is not None and (not isinstance(tool_name, str) or tool_name not in allowed_tool_name):
        return _err("VALIDATION_ERROR", "Invalid tool_name filter.", allowed=sorted(list(allowed_tool_name)))

    if limit is None:
        limit = 20
    if not isinstance(limit, int):
        return _err("VALIDATION_ERROR", "limit must be an integer.")
    if limit < 1 or limit > 100:
        return _err("VALIDATION_ERROR", "limit out of range (1-100).")

    cobj = None
    if cursor is not None:
        cobj = _decode_cursor(cursor)
        if cobj is None:
            return _err("VALIDATION_ERROR", "Invalid cursor.")

    # Load jobs and filter to calling key
    jobs = _load("generation_jobs.json")
    my_jobs = []
    for j in jobs:
        if not isinstance(j, dict):
            continue
        if j.get("api_key_id") != key.get("id"):
            continue
        if status is not None and j.get("status") != status:
            continue
        if job_type is not None and j.get("job_type") != job_type:
            continue
        if tool_name is not None and j.get("tool_name") != tool_name:
            continue
        my_jobs.append(j)

    # Order by created_at desc (fallback to updated_at)
    def sort_key(j):
        dt = _parse_dt(j.get("created_at")) or _parse_dt(j.get("updated_at")) or datetime.datetime.fromtimestamp(0, tz=datetime.timezone.utc)
        # desc: use negative timestamp
        return (dt, j.get("id") or "")

    my_jobs.sort(key=sort_key, reverse=True)

    # Apply cursor (exclusive): items after cursor in this ordering
    if cobj:
        c_dt = _parse_dt(cobj["created_at"]) or datetime.datetime.fromtimestamp(0, tz=datetime.timezone.utc)
        c_id = cobj["id"]

        def after_cursor(j):
            j_dt = _parse_dt(j.get("created_at")) or _parse_dt(j.get("updated_at")) or datetime.datetime.fromtimestamp(0, tz=datetime.timezone.utc)
            j_id = j.get("id") or ""
            # Since sorted desc, "after" means strictly less than cursor tuple in desc ordering
            if j_dt < c_dt:
                return True
            if j_dt == c_dt and j_id < c_id:
                return True
            return False

        my_jobs = [j for j in my_jobs if after_cursor(j)]

    page = my_jobs[:limit]
    has_more = len(my_jobs) > len(page)
    next_cursor = None
    if page:
        last = page[-1]
        last_ca = last.get("created_at") or last.get("updated_at") or _now()
        last_id = last.get("id") or ""
        next_cursor = _encode_cursor(last_ca, last_id) if has_more else None

    # Record usage event (read-only compute_ms=0)
    usage = _load("usage_events.json")
    now = _now()
    evt = {
        "id": _gen_id("rfx_use_"),
        "api_key_id": key.get("id"),
        "tool_name": "prediction_list" if False else "prediction_list",  # placeholder; corrected below
        "job_id": None,
        "prediction_id": None,
        "request_payload": {
            "status": status,
            "job_type": job_type,
            "tool_name": tool_name,
            "limit": limit,
            "cursor": cursor,
        },
        "response_summary": {
            "returned": len(page),
            "total_matched": len(my_jobs),
            "has_more": has_more,
        },
        "compute_ms": 0,
        "created_at": now,
        "updated_at": now,
    }
    # There is no usage_events tool_name value for "job_list" in schema.
    # To avoid violating enum constraints, we log under "prediction_list" (closest read/list tool).
    evt["tool_name"] = "prediction_list"
    usage.append(evt)
    _save("usage_events.json", usage)

    # Update last_used_at on successful auth/use
    for k in api_keys:
        if isinstance(k, dict) and k.get("id") == key.get("id"):
            k["last_used_at"] = now
            k["updated_at"] = now
            break
    _save("api_keys.json", api_keys)

    latency_ms = int((time.time() - t0) * 1000)
    return {
        "jobs": page,
        "meta": {
            "limit": limit,
            "total": len(my_jobs),
            "has_more": has_more,
            "next_cursor": next_cursor,
            "latency_ms": latency_ms,
        },
    }

def cancel_job(job_id, reason=None, **_extra):
    import json, os, datetime, time, uuid, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0015000" if __import__("os").path.isdir("./environment_mix/0015000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now():
        return datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc)

    def _now_iso():
        return _now().isoformat().replace("+00:00", "Z")

    def _parse_dt(v):
        if not v or not isinstance(v, str):
            return None
        try:
            s = v[:-1] + "+00:00" if v.endswith("Z") else v
            return datetime.datetime.fromisoformat(s).astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _new_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex[:20].upper()}"

    def _record_usage(api_key_id, tool_name, status_code, request_payload=None, response_summary=None, compute_ms=0, job_id=None, prediction_id=None):
        usage = _load("usage_events.json")
        if not isinstance(usage, list):
            usage = []
        now = _now_iso()
        usage.append({
            "id": _new_id("rfx_use"),
            "api_key_id": api_key_id,
            "tool_name": tool_name,
            "job_id": job_id,
            "prediction_id": prediction_id,
            "request_payload": request_payload,
            "response_summary": {"status": status_code, **(response_summary or {})},
            "compute_ms": int(compute_ms) if isinstance(compute_ms, int) and compute_ms >= 0 else 0,
            "created_at": now,
            "updated_at": now
        })
        _save("usage_events.json", usage)

    def _resolve_active_api_key_for_job(target_job):
        api_keys = _load("api_keys.json")
        if not isinstance(api_keys, list):
            api_keys = []
        active = [k for k in api_keys if isinstance(k, dict) and k.get("status") == "active" and isinstance(k.get("id"), str)]
        if not active:
            return None
        # Prefer the owning key (most "realistic" ambient auth resolution), else any active key.
        owner_id = target_job.get("api_key_id")
        if isinstance(owner_id, str):
            for k in active:
                if k.get("id") == owner_id:
                    return k
        active.sort(key=lambda r: (r.get("last_used_at") or r.get("updated_at") or r.get("created_at") or ""), reverse=True)
        return active[0] if active else None

    def _derive_job_status(job_row, preds_for_job):
        # Business rule: derived from child predictions unless explicitly cancelled.
        if job_row.get("status") == "cancelled":
            return "cancelled"
        if not preds_for_job:
            return "queued"
        any_running = any(p.get("status") in ("starting", "processing") for p in preds_for_job)
        any_failed = any(p.get("status") == "failed" for p in preds_for_job)
        all_succeeded = all(p.get("status") == "succeeded" for p in preds_for_job)
        if any_running:
            return "running"
        if all_succeeded:
            return "succeeded"
        if any_failed:
            return "failed"
        # remaining: only canceled predictions or odd mixes -> treat as queued unless explicitly cancelled
        return "queued"

    # Validate inputs
    if not isinstance(job_id, str) or not re.match(r"^rfx_job_[0-9A-Z]{17,}$", job_id):
        return _err("VALIDATION_ERROR", "Invalid job_id format.", job_id=job_id)
    if reason is not None:
        if not isinstance(reason, str):
            return _err("VALIDATION_ERROR", "reason must be a string.", reason=reason)
        if len(reason) > 500:
            return _err("VALIDATION_ERROR", "reason exceeds maxLength 500.", maxLength=500)

    jobs = _load("generation_jobs.json")
    if not isinstance(jobs, list):
        jobs = []
    job = None
    job_idx = None
    for i, r in enumerate(jobs):
        if isinstance(r, dict) and r.get("id") == job_id:
            job = r
            job_idx = i
            break
    if not job:
        # must still record usage, but we need an active key context to charge. Choose any active key if exists.
        api_keys = _load("api_keys.json")
        if not isinstance(api_keys, list):
            api_keys = []
        any_active = next((k for k in api_keys if isinstance(k, dict) and k.get("status") == "active" and isinstance(k.get("id"), str)), None)
        if any_active:
            _record_usage(any_active["id"], "generate_image", 404, request_payload={"job_id": job_id, "reason": reason}, response_summary={"error": "NOT_FOUND"}, compute_ms=0, job_id=None)
        return _err("NOT_FOUND", "Job not found.", job_id=job_id)

    # Authenticate (ambient) to exactly one active api_keys row
    api_key_row = _resolve_active_api_key_for_job(job)
    if not api_key_row:
        return _err("UNAUTHORIZED", "No active API key available to authorize this request (business rule: every tool invocation must authenticate to exactly one active api_keys row).")

    # Enforce job ownership access (use derived ambient key; if it's not owner, refuse)
    if job.get("api_key_id") != api_key_row.get("id"):
        _record_usage(api_key_row["id"], "generate_image", 401, request_payload={"job_id": job_id, "reason": reason}, response_summary={"error": "UNAUTHORIZED", "job_id": job_id}, compute_ms=0, job_id=job_id)
        return _err("UNAUTHORIZED", "Job is not accessible with the current API key (business rule: refuse requests for jobs owned by other API keys).", job_id=job_id)

    # Validate cancellable state
    if job.get("status") in ("succeeded", "failed", "cancelled"):
        _record_usage(api_key_row["id"], "generate_image", 409, request_payload={"job_id": job_id, "reason": reason}, response_summary={"error": "INVALID_TRANSITION", "job_id": job_id, "status": job.get("status")}, compute_ms=0, job_id=job_id)
        return _err("INVALID_TRANSITION", "Cannot cancel a terminal job (business rule: refuses cancellation for terminal jobs).", job_id=job_id, status=job.get("status"))

    preds = _load("replicate_predictions.json")
    if not isinstance(preds, list):
        preds = []
    now_iso = _now_iso()

    updated_predictions = []
    # Attempt to cancel non-terminal linked predictions
    for p in preds:
        if not isinstance(p, dict):
            continue
        if p.get("job_id") != job_id:
            continue
        # Only affect predictions belonging to same api key (should be true by FK/business rules)
        if p.get("api_key_id") != api_key_row.get("id"):
            continue
        st = p.get("status")
        if st in ("succeeded", "failed", "canceled"):
            continue
        # enforce valid transition to canceled
        if st not in ("starting", "processing"):
            # If status is missing/unknown, refuse rather than corrupt.
            _record_usage(api_key_row["id"], "generate_image", 409, request_payload={"job_id": job_id, "reason": reason}, response_summary={"error": "INVALID_TRANSITION", "prediction_id": p.get("id"), "status": st}, compute_ms=0, job_id=job_id, prediction_id=p.get("id"))
            return _err("INVALID_TRANSITION", "Cannot cancel prediction from its current status (business rule: status update must follow declared transitions).", prediction_id=p.get("id"), status=st)

        p["status"] = "canceled"
        # terminal: allow late logs/metrics later, but set error_message now
        if isinstance(reason, str) and reason.strip():
            p["error_message"] = f"Canceled: {reason.strip()}"
        else:
            if not p.get("error_message"):
                p["error_message"] = "Prediction canceled by user."
        p["updated_at"] = now_iso
        updated_predictions.append(p)

    # Cancel job itself (explicit cancel)
    job["status"] = "cancelled"
    if isinstance(reason, str) and reason.strip():
        job["error_message"] = f"User cancelled: {reason.strip()}"
    else:
        if not job.get("error_message"):
            job["error_message"] = "User cancelled before prediction started."
    job["updated_at"] = now_iso
    jobs[job_idx] = job

    # Persist changes
    _save("replicate_predictions.json", preds)
    _save("generation_jobs.json", jobs)

    # Update last_used_at for api key on successful call
    api_keys = _load("api_keys.json")
    if isinstance(api_keys, list):
        for k in api_keys:
            if isinstance(k, dict) and k.get("id") == api_key_row["id"]:
                k["last_used_at"] = now_iso
                k["updated_at"] = now_iso
                break
        _save("api_keys.json", api_keys)

    # Record usage event (tool_name enum doesn't include cancel_job; charge under closest write tool as request snapshot)
    latency_ms = int((time.time() - t0) * 1000)
    _record_usage(
        api_key_row["id"],
        "create_prediction",
        200,
        request_payload={"job_id": job_id, "reason": reason},
        response_summary={"job_id": job_id, "cancelled_predictions": len(updated_predictions), "latency_ms": latency_ms},
        compute_ms=0,
        job_id=job_id
    )

    # Return updated job and any updated predictions
    return {
        "job": job,
        "predictions": updated_predictions,
        "meta": {
            "job_status_derived": _derive_job_status(job, [p for p in preds if isinstance(p, dict) and p.get("job_id") == job_id]),
            "cancelled_predictions": len(updated_predictions)
        }
    }

def cancel_prediction(prediction_id, reason=None, **_extra):
    import json, os, datetime, time, uuid, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0015000" if __import__("os").path.isdir("./environment_mix/0015000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now():
        return datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc)

    def _now_iso():
        return _now().isoformat().replace("+00:00", "Z")

    def _new_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex[:20].upper()}"

    def _record_usage(api_key_id, tool_name, status_code, request_payload=None, response_summary=None, compute_ms=0, job_id=None, prediction_id=None):
        usage = _load("usage_events.json")
        if not isinstance(usage, list):
            usage = []
        now = _now_iso()
        usage.append({
            "id": _new_id("rfx_use"),
            "api_key_id": api_key_id,
            "tool_name": tool_name,
            "job_id": job_id,
            "prediction_id": prediction_id,
            "request_payload": request_payload,
            "response_summary": {"status": status_code, **(response_summary or {})},
            "compute_ms": int(compute_ms) if isinstance(compute_ms, int) and compute_ms >= 0 else 0,
            "created_at": now,
            "updated_at": now
        })
        _save("usage_events.json", usage)

    def _resolve_active_api_key_for_prediction(target_pred):
        api_keys = _load("api_keys.json")
        if not isinstance(api_keys, list):
            api_keys = []
        active = [k for k in api_keys if isinstance(k, dict) and k.get("status") == "active" and isinstance(k.get("id"), str)]
        if not active:
            return None
        owner_id = target_pred.get("api_key_id")
        if isinstance(owner_id, str):
            for k in active:
                if k.get("id") == owner_id:
                    return k
        active.sort(key=lambda r: (r.get("last_used_at") or r.get("updated_at") or r.get("created_at") or ""), reverse=True)
        return active[0] if active else None

    # Validate inputs
    if not isinstance(prediction_id, str) or not re.match(r"^rfx_pred_[0-9A-Z]{17,}$", prediction_id):
        return _err("VALIDATION_ERROR", "Invalid prediction_id format.", prediction_id=prediction_id)
    if reason is not None:
        if not isinstance(reason, str):
            return _err("VALIDATION_ERROR", "reason must be a string.", reason=reason)
        if len(reason) > 500:
            return _err("VALIDATION_ERROR", "reason exceeds maxLength 500.", maxLength=500)

    preds = _load("replicate_predictions.json")
    if not isinstance(preds, list):
        preds = []
    pred = None
    pred_idx = None
    for i, r in enumerate(preds):
        if isinstance(r, dict) and r.get("id") == prediction_id:
            pred = r
            pred_idx = i
            break
    if not pred:
        # record usage if possible
        api_keys = _load("api_keys.json")
        if not isinstance(api_keys, list):
            api_keys = []
        any_active = next((k for k in api_keys if isinstance(k, dict) and k.get("status") == "active" and isinstance(k.get("id"), str)), None)
        if any_active:
            _record_usage(any_active["id"], "create_prediction", 404, request_payload={"prediction_id": prediction_id, "reason": reason}, response_summary={"error": "NOT_FOUND"}, compute_ms=0, prediction_id=None)
        return _err("NOT_FOUND", "Prediction not found.", prediction_id=prediction_id)

    # Authenticate (ambient) to exactly one active api_keys row
    api_key_row = _resolve_active_api_key_for_prediction(pred)
    if not api_key_row:
        return _err("UNAUTHORIZED", "No active API key available to authorize this request (business rule: every tool invocation must authenticate to exactly one active api_keys row).")

    # Enforce access
    if pred.get("api_key_id") != api_key_row.get("id"):
        _record_usage(api_key_row["id"], "create_prediction", 401, request_payload={"prediction_id": prediction_id, "reason": reason}, response_summary={"error": "UNAUTHORIZED", "prediction_id": prediction_id}, compute_ms=0, prediction_id=prediction_id)
        return _err("UNAUTHORIZED", "Prediction is not accessible with the current API key (business rule: refuse requests for predictions owned by other API keys).", prediction_id=prediction_id)

    st = pred.get("status")
    if st in ("succeeded", "failed", "canceled"):
        _record_usage(api_key_row["id"], "create_prediction", 409, request_payload={"prediction_id": prediction_id, "reason": reason}, response_summary={"error": "INVALID_TRANSITION", "prediction_id": prediction_id, "status": st}, compute_ms=0, prediction_id=prediction_id)
        return _err("INVALID_TRANSITION", "Cannot cancel a terminal prediction (business rule: refuses cancellation for terminal predictions).", prediction_id=prediction_id, status=st)

    # Only starting/processing are cancellable per tool description; enforce lifecycle transition validity
    if st not in ("starting", "processing"):
        _record_usage(api_key_row["id"], "create_prediction", 409, request_payload={"prediction_id": prediction_id, "reason": reason}, response_summary={"error": "INVALID_TRANSITION", "prediction_id": prediction_id, "status": st}, compute_ms=0, prediction_id=prediction_id)
        return _err("INVALID_TRANSITION", "Cannot cancel prediction from its current status (business rule: status update must follow declared transitions).", prediction_id=prediction_id, status=st)

    now_iso = _now_iso()
    pred["status"] = "canceled"
    if isinstance(reason, str) and reason.strip():
        pred["error_message"] = f"Canceled: {reason.strip()}"
    else:
        if not pred.get("error_message"):
            pred["error_message"] = "Prediction canceled by user."
    pred["updated_at"] = now_iso
    preds[pred_idx] = pred

    _save("replicate_predictions.json", preds)

    # Update owning job status if linked (derived from children unless explicitly cancelled)
    job_id = pred.get("job_id")
    if isinstance(job_id, str):
        jobs = _load("generation_jobs.json")
        if not isinstance(jobs, list):
            jobs = []
        job_idx = next((i for i, j in enumerate(jobs) if isinstance(j, dict) and j.get("id") == job_id), None)
        if job_idx is not None:
            job = jobs[job_idx]
            if isinstance(job, dict) and job.get("api_key_id") == api_key_row.get("id"):
                # if job already cancelled, keep; else if job was queued/running, keep status unless it becomes "queued" by derivation
                preds_for_job = [p for p in preds if isinstance(p, dict) and p.get("job_id") == job_id and p.get("api_key_id") == api_key_row.get("id")]
                if job.get("status") != "cancelled":
                    any_running = any(p.get("status") in ("starting", "processing") for p in preds_for_job)
                    any_failed = any(p.get("status") == "failed" for p in preds_for_job)
                    all_succeeded = bool(preds_for_job) and all(p.get("status") == "succeeded" for p in preds_for_job)
                    if any_running:
                        derived = "running"
                    elif all_succeeded:
                        derived = "succeeded"
                    elif any_failed:
                        derived = "failed"
                    else:
                        derived = "queued"
                    if job.get("status") in ("queued", "running") and derived in ("queued", "running", "succeeded", "failed"):
                        job["status"] = derived
                        job["updated_at"] = now_iso
                        jobs[job_idx] = job
                        _save("generation_jobs.json", jobs)

    # Update last_used_at on success
    api_keys = _load("api_keys.json")
    if isinstance(api_keys, list):
        for k in api_keys:
            if isinstance(k, dict) and k.get("id") == api_key_row["id"]:
                k["last_used_at"] = now_iso
                k["updated_at"] = now_iso
                break
        _save("api_keys.json", api_keys)

    latency_ms = int((time.time() - t0) * 1000)
    _record_usage(
        api_key_row["id"],
        "create_prediction",
        200,
        request_payload={"prediction_id": prediction_id, "reason": reason},
        response_summary={"prediction_id": prediction_id, "status": pred.get("status"), "latency_ms": latency_ms},
        compute_ms=0,
        job_id=job_id if isinstance(job_id, str) else None,
        prediction_id=prediction_id
    )

    return {"prediction": pred}
